import { expect, test } from 'bun:test'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { canonicalBytes, canonicalDigest } from './agent-profile-canonical'
// Removal runs use an owned temporary copy; tracked generated bytes stay exact.
const C: typeof import('./agent-profile-contract') = await import(
  process.env.TEST_GILD_PROFILE_CONTRACT ??
    resolve('src/api/agent-profile-contract.ts')
)
const owner = '11111111-1111-4111-8111-111111111111',
  agent = '22222222-2222-4222-8222-222222222222'
function profile(): import('./agent-profile-contract').ProfileRevision {
  return JSON.parse(
    readFileSync(
      'scripts/fixtures/skills/agent-profile-revision-v1.json',
      'utf8',
    ),
  )
}
function replacement(expectedRevisionId: string | null) {
  const p = profile()
  return {
    contractVersion: 1,
    expectedRevisionId,
    persona: p.persona,
    runtime: p.runtime,
    skills: p.skills,
    desiredControls: p.desiredControls,
  }
}
function report(): import('./agent-profile-contract').RuntimeSupportReport {
  return {
    contractVersion: 1,
    reportId: 'report-1',
    harnessId: 'codex',
    harnessVersion: 'fixture-1',
    adapterVersion: 'fixture-v1',
    executionMode: 'host',
    processIsolation: 'owned-process',
    discovery: { available: true, methods: ['skills/list'] },
    delivery: { status: 'verified', modes: ['interactive'] },
    controls: {
      filesystem: {
        status: 'advisory',
        boundary: 'owned-host-process',
        trust: 'owner-local-report',
        evidenceIds: ['evidence-1'],
      },
      network: {
        status: 'advisory',
        boundary: 'owned-host-process',
        trust: 'owner-local-report',
        evidenceIds: ['evidence-1'],
      },
      tools: {
        status: 'advisory',
        boundary: 'owned-host-process',
        trust: 'owner-local-report',
        evidenceIds: ['evidence-1'],
      },
      delegation: {
        status: 'advisory',
        boundary: 'owned-host-process',
        trust: 'owner-local-report',
        evidenceIds: ['evidence-1'],
      },
    },
    evidence: [
      {
        id: 'evidence-1',
        reference: 'fixture:declaration-only',
        version: 'fixture-1',
        digest: '1'.repeat(64),
        observedAt: '2026-10-11T12:00:00Z',
        limits: 'Synthetic declaration; no real delivery or enforcement.',
      },
    ],
  }
}
async function fixture() {
  const p = profile(),
    r = report(),
    manifest = JSON.parse(
      readFileSync(
        'scripts/fixtures/skills/ecc-verification-loop.manifest.json',
        'utf8',
      ),
    )
  const pin = await C.skillManifestIdentity(manifest)
  const selection = {
    pinId: pin.pinId,
    bundleDigest: pin.bundleDigest,
    entryDigest: pin.entryDigest,
  }
  p.skills = [selection]
  const snapshot: import('./agent-profile-contract').RunSnapshot = {
    contractVersion: 1,
    snapshotId: 'snapshot-1',
    agentIdentityId: agent,
    ownerIdentityId: owner,
    profileRevisionId: p.revisionId,
    profileDigest: await canonicalDigest(p),
    createdAt: p.createdAt,
    runtime: { ...p.runtime },
    skills: [{ selection, manifest }],
    supportReportId: r.reportId,
    supportReportDigest: await canonicalDigest(r),
  }
  return { p, r, snapshot }
}
function fault(action: () => unknown, code: string, status: number) {
  let error: unknown
  try {
    action()
  } catch (e) {
    error = e
  }
  expect(error).toBeInstanceOf(C.AgentProfileContractError)
  expect({
    code: (error as InstanceType<typeof C.AgentProfileContractError>).code,
    status: (error as InstanceType<typeof C.AgentProfileContractError>).status,
  }).toEqual({ code, status })
}
async function rejection(action: () => Promise<unknown>, code: string) {
  let error: unknown
  try {
    await action()
  } catch (e) {
    error = e
  }
  expect(error).toBeInstanceOf(C.AgentProfileContractError)
  expect({
    code: (error as InstanceType<typeof C.AgentProfileContractError>).code,
    status: (error as InstanceType<typeof C.AgentProfileContractError>).status,
  }).toEqual({ code, status: 422 })
}

test('actual canonical parser reproduces frozen806-byte profile vector and immutable ECC vector', async () => {
  const raw = readFileSync(
      'scripts/fixtures/skills/agent-profile-revision-v1.json',
    ),
    parsed = C.parseProfileRevision(JSON.parse(raw.toString()))
  expect(raw.length).toBe(806)
  expect(Buffer.from(canonicalBytes(parsed))).toEqual(raw)
  expect(await canonicalDigest(parsed)).toBe(
    '5d305adee182d62eed11d5a68ba41892739ce29c65e7647f49ffa2b62b95e024',
  )
  const { snapshot } = await fixture()
  expect(snapshot.skills[0].selection.bundleDigest).toBe(
    '8642aec70aefee472151de8b27fc97a08ff9bb85bf927fb69afc53a4ae499d6c',
  )
})
test('own profile preconditions retain missing428 and stale412 before body validation', () => {
  fault(
    () => C.parseReplaceProfileInput({ unexpected: true }, null),
    'PRECONDITION_REQUIRED',
    428,
  )
  fault(
    () =>
      C.parseReplaceProfileInput(
        { expectedRevisionId: 'old', contractVersion: 2, unexpected: true },
        'rev-1',
      ),
    'REVISION_STALE',
    412,
  )
  expect(
    C.parseReplaceProfileInput(replacement(null), null).expectedRevisionId,
  ).toBeNull()
  fault(
    () => C.parseReplaceProfileInput(replacement(null), 'rev-1'),
    'REVISION_STALE',
    412,
  )
  fault(
    () =>
      C.parseReplaceProfileInput(
        { ...replacement(null), expectedRevisionId: undefined },
        null,
      ),
    'VALIDATION_FAILED',
    422,
  )
})
test('precondition accessors never execute and inherited values never satisfy ownership', () => {
  let calls = 0
  const getter = Object.defineProperty(
    replacement(null),
    'expectedRevisionId',
    {
      enumerable: true,
      get() {
        calls++
        return null
      },
    },
  )
  fault(
    () => C.parseReplaceProfileInput(getter, null),
    'VALIDATION_FAILED',
    422,
  )
  expect(calls).toBe(0)
  const inherited = { ...replacement(null) } as Record<string, unknown>
  delete inherited.expectedRevisionId
  Object.setPrototypeOf(inherited, { expectedRevisionId: null })
  fault(
    () => C.parseReplaceProfileInput(inherited, null),
    'PRECONDITION_REQUIRED',
    428,
  )
})
test('replacement and rollback stale revisions precede invalid canonical body fields', () => {
  for (const invalid of [-1, '\ud800']) {
    for (const parse of [
      C.parseReplaceProfileInput,
      C.parseRollbackProfileInput,
    ]) {
      fault(
        () => parse({ expectedRevisionId: 'old', invalid }, 'rev-1'),
        'REVISION_STALE',
        412,
      )
      fault(
        () => parse({ expectedRevisionId: 'rev-1', invalid }, 'rev-1'),
        'VALIDATION_FAILED',
        422,
      )
      fault(() => parse({ invalid }, 'rev-1'), 'PRECONDITION_REQUIRED', 428)
      fault(
        () => parse({ expectedRevisionId: 123, invalid }, 'rev-1'),
        'VALIDATION_FAILED',
        422,
      )
    }
  }
})
test('rollback input parses explicit revision data with typed stable preconditions', () => {
  expect(
    C.parseRollbackProfileInput(
      {
        contractVersion: 1,
        expectedRevisionId: 'rev-1',
        restoreRevisionId: 'rev-0',
      },
      'rev-1',
    ),
  ).toEqual({
    contractVersion: 1,
    expectedRevisionId: 'rev-1',
    restoreRevisionId: 'rev-0',
  })
  fault(
    () =>
      C.parseRollbackProfileInput(
        { contractVersion: 1, restoreRevisionId: 'rev-0' },
        'rev-1',
      ),
    'PRECONDITION_REQUIRED',
    428,
  )
  fault(
    () =>
      C.parseRollbackProfileInput(
        {
          contractVersion: 1,
          expectedRevisionId: 'old',
          restoreRevisionId: 'rev-0',
        },
        'rev-1',
      ),
    'REVISION_STALE',
    412,
  )
})
test('strict profile controls reject credentials machine fields unknown authority and unsupported version', () => {
  const changes: Array<(p: any) => void> = [
    (p) => {
      p.token = 'fixture-forbidden'
    },
    (p) => {
      p.env = { secret: 'fixture-forbidden' }
    },
    (p) => {
      p.runtime.cwd = '/private/path'
    },
    (p) => {
      p.desiredControls.delegation.allow = true
    },
    (p) => {
      delete p.desiredControls.tools.requireEnforced
    },
    (p) => {
      p.desiredControls.filesystem.readProjectIds = ['/host/path']
    },
    (p) => {
      p.desiredControls.filesystem.readProjectIds = ['b', 'a']
    },
    (p) => {
      p.previousRevisionId = p.revisionId
    },
    (p) => {
      p.rollbackOf = p.revisionId
    },
    (p) => {
      p.persona.instructions = '\ud800'
    },
  ]
  for (const change of changes) {
    const p = profile()
    change(p)
    fault(() => C.parseProfileRevision(p), 'VALIDATION_FAILED', 422)
  }
  fault(
    () => C.parseProfileRevision({ ...profile(), contractVersion: 2 }),
    'CONTRACT_UNSUPPORTED',
    422,
  )
})
test('exact DNS controls reject IP shorthand credentials wildcards ports URLs and case aliases', () => {
  for (const host of [
    '127.0.0.1',
    '127.1',
    '0x7f000001',
    '2130706433',
    '*.example.com',
    'user@example.com',
    'example.com:443',
    'example.com/path',
    'Example.com',
  ]) {
    const p = profile()
    p.desiredControls.network.mode = 'allow-listed'
    p.desiredControls.network.hosts = [host]
    fault(() => C.parseProfileRevision(p), 'VALIDATION_FAILED', 422)
  }
  const p = profile()
  p.desiredControls.network.mode = 'allow-listed'
  p.desiredControls.network.hosts = ['example.com']
  expect(C.parseProfileRevision(p).desiredControls.network.hosts).toEqual([
    'example.com',
  ])
})
test('declared support evidence is consistent data and is never synthesized from discovery', () => {
  const r = report()
  r.controls.network.evidenceIds = ['missing']
  fault(() => C.parseRuntimeSupportReport(r), 'VALIDATION_FAILED', 422)
  const duplicate = report()
  duplicate.evidence.push({ ...duplicate.evidence[0] })
  fault(() => C.parseRuntimeSupportReport(duplicate), 'VALIDATION_FAILED', 422)
  const absent = report()
  absent.discovery.available = false
  fault(() => C.parseRuntimeSupportReport(absent), 'VALIDATION_FAILED', 422)
  expect(C.parseRuntimeSupportReport(report()).controls.network.status).toBe(
    'advisory',
  )
})
test('snapshot binds exact profile generations revision digest runtime and support data', async () => {
  const { p, r, snapshot } = await fixture()
  expect(
    await C.verifyRunSnapshotArtifacts(snapshot, p, r, 'interactive'),
  ).toEqual(snapshot)
  const changes: Array<(s: any) => void> = [
    (s) => {
      s.ownerIdentityId = agent
    },
    (s) => {
      s.agentIdentityId = owner
    },
    (s) => {
      s.profileRevisionId = 'other'
    },
    (s) => {
      s.profileDigest = '0'.repeat(64)
    },
    (s) => {
      s.runtime.model = 'changed'
    },
    (s) => {
      s.runtime.adapterVersion = 'changed'
    },
    (s) => {
      s.supportReportId = 'other'
    },
    (s) => {
      s.supportReportDigest = '0'.repeat(64)
    },
  ]
  for (const change of changes) {
    const s = structuredClone(snapshot)
    change(s)
    await rejection(
      () => C.verifyRunSnapshotArtifacts(s, p, r, 'interactive'),
      'VALIDATION_FAILED',
    )
  }
  const changed = structuredClone(r)
  changed.harnessVersion = 'different'
  await rejection(
    () => C.verifyRunSnapshotArtifacts(snapshot, p, changed, 'interactive'),
    'VALIDATION_FAILED',
  )
})
test('snapshot requires complete ordered immutable pin and manifest binding', async () => {
  const { p, r, snapshot } = await fixture()
  await rejection(
    async () =>
      C.verifyRunSnapshotArtifacts(
        { ...snapshot, skills: [] },
        p,
        r,
        'interactive',
      ),
    'SKILL_UNSUPPORTED',
  )
  const corrupt = structuredClone(snapshot)
  corrupt.skills[0].manifest.metadata.description += 'changed'
  await rejection(
    () => C.verifyRunSnapshotArtifacts(corrupt, p, r, 'interactive'),
    'SKILL_UNSUPPORTED',
  )
  const bad = structuredClone(snapshot),
    changed = structuredClone(p)
  bad.skills[0].selection.entryDigest = 'a'.repeat(64)
  changed.skills[0] = bad.skills[0].selection
  bad.profileDigest = await canonicalDigest(changed)
  await rejection(
    () => C.verifyRunSnapshotArtifacts(bad, changed, r, 'interactive'),
    'SKILL_UNSUPPORTED',
  )
  // A second distinct synthetic manifest makes reordering independently visible.
  const second = structuredClone(snapshot.skills[0].manifest)
  second.skillId = 'second-fixture'
  const identity = await C.skillManifestIdentity(second)
  const selection = {
    pinId: identity.pinId,
    bundleDigest: identity.bundleDigest,
    entryDigest: identity.entryDigest,
  }
  const orderedProfile = structuredClone(p)
  orderedProfile.skills.push(selection)
  const ordered = {
    ...snapshot,
    profileDigest: await canonicalDigest(orderedProfile),
    skills: [...snapshot.skills, { selection, manifest: second }],
  }
  expect(
    await C.verifyRunSnapshotArtifacts(
      ordered,
      orderedProfile,
      r,
      'interactive',
    ),
  ).toEqual(ordered)
  await rejection(
    () =>
      C.verifyRunSnapshotArtifacts(
        { ...ordered, skills: [...ordered.skills].reverse() },
        orderedProfile,
        r,
        'interactive',
      ),
    'SKILL_UNSUPPORTED',
  )
})
test('discovery cannot substitute for declared verified delivery in requested mode', async () => {
  const { p, r, snapshot } = await fixture(),
    unverified = structuredClone(r)
  unverified.delivery.status = 'unverified'
  await rejection(
    async () =>
      C.verifyRunSnapshotArtifacts(
        { ...snapshot, supportReportDigest: await canonicalDigest(unverified) },
        p,
        unverified,
        'interactive',
      ),
    'DELIVERY_UNVERIFIED',
  )
  await rejection(
    () => C.verifyRunSnapshotArtifacts(snapshot, p, r, 'piped'),
    'DELIVERY_UNVERIFIED',
  )
})
test('each required control rejects advisory unsupported and unverified enforcement', async () => {
  const { p, r, snapshot } = await fixture()
  for (const key of ['filesystem', 'network', 'tools', 'delegation'] as const) {
    const required = structuredClone(p)
    required.desiredControls[key].requireEnforced = true
    await rejection(
      async () =>
        C.verifyRunSnapshotArtifacts(
          { ...snapshot, profileDigest: await canonicalDigest(required) },
          required,
          r,
          'interactive',
        ),
      'ENFORCEMENT_UNSUPPORTED',
    )
    const unsupported = structuredClone(r)
    unsupported.controls[key].status = 'unsupported'
    await rejection(
      async () =>
        C.verifyRunSnapshotArtifacts(
          {
            ...snapshot,
            profileDigest: await canonicalDigest(required),
            supportReportDigest: await canonicalDigest(unsupported),
          },
          required,
          unsupported,
          'interactive',
        ),
      'ENFORCEMENT_UNSUPPORTED',
    )
    const unavailable = structuredClone(r)
    unavailable.controls[key].status = 'enforced'
    unavailable.controls[key].boundary = 'unverified'
    await rejection(
      async () =>
        C.verifyRunSnapshotArtifacts(
          {
            ...snapshot,
            profileDigest: await canonicalDigest(required),
            supportReportDigest: await canonicalDigest(unavailable),
          },
          required,
          unavailable,
          'interactive',
        ),
      'ENFORCEMENT_UNSUPPORTED',
    )
  }
})
test('data artifact verification supplies no authority or launch permit', async () => {
  const { p, r, snapshot } = await fixture()
  // These declarations are synthetic, not evidence of real support/authentication.
  const parsed = await C.verifyRunSnapshotArtifacts(
    snapshot,
    p,
    r,
    'interactive',
  )
  expect(Object.keys(parsed)).not.toContain('launchPermit')
  expect(Object.keys(parsed)).not.toContain('executionClaim')
  fault(
    () => C.parseRunSnapshot({ ...snapshot, launchPermit: true }),
    'VALIDATION_FAILED',
    422,
  )
  expect(C.parseProfileRevision(p).ownerIdentityId).toBe(owner)
})
